public static func splitPane(
    available: CGFloat, preferred: CGFloat, firstFloor: CGFloat, secondFloor: CGFloat
) -> CGFloat {
    guard available > 0 else { return 0 }
    guard available >= firstFloor + secondFloor else {
        return available * firstFloor / (firstFloor + secondFloor)
    }
    return min(max(preferred, firstFloor), available - secondFloor)
}

func splitView(_ splitView: NSSplitView, resizeSubviewsWithOldSize oldSize: NSSize) {
    if splitView === columnSplit {
        layoutColumnPanes()
    } else if splitView === outerSplit {
        layoutOuterPanes()
    } else {
        splitView.adjustSubviews()
    }
}

override func viewDidLayout() {
    super.viewDidLayout()
    layoutOuterPanes()
    layoutColumnPanes()
}

func splitView(
    _ splitView: NSSplitView, constrainMaxCoordinate proposedMaximumPosition: CGFloat,
    ofSubviewAt dividerIndex: Int
) -> CGFloat {
    if splitView === outerSplit { /* the same, across, with the list and diff widths */ }
    guard splitView === columnSplit else { return proposedMaximumPosition }
    let lastOpen =
        splitView.bounds.height - splitView.dividerThickness - Self.detailPaneFloor
    return min(proposedMaximumPosition, max(Self.commitsPaneFloor, lastOpen))
}

